\multicolumn{2}{r}{} & -x^4 & -x^3 \\ \cline{3-4}
\multicolumn{2}{r}{} & 0 & +x^3 & +0x^2 \\
\multicolumn{2}{r}{} & & +x^3 & +x^2 \\ \cline{4-5}
\multicolumn{2}{r}{} & & 0 & -x^2 & +0x \\
\multicolumn{2}{r}{} & & & -x^2 & -x \\ \cline{5-6}
\multicolumn{2}{r}{} & & & 0 & +x & +7 \\
\multicolumn{2}{r}{} & & & & +x & +1 \\ \cline{6-7}
\multicolumn{2}{r}{} & & & & 0 & +6 \\
\end{array}
\]
